{"path":"assets/css/styles.css","content":"/* Zen minimal clinical stylesheet */
:root{
  --bg:#fbfbfb;
  --muted:#6b6b6b;
  --accent:#3b6b63;
  --accent-2:#2e547f;
  --card:#ffffff;
  --shadow:0 6px 18px rgba(30,30,30,0.06);
  --max-width:1100px;
  --radius:10px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:#1f2933;background:var(--bg);-webkit-font-smoothing:antialiased}
.container{max-width:var(--max-width);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.7),transparent);backdrop-filter:blur(4px);position:sticky;top:0;z-index:50;border-bottom:1px solid rgba(20,20,20,0.04)}
.site-header .container{display:flex;align-items:center;gap:18px}
.brand{font-weight:600;color:var(--accent-2);text-decoration:none}
.main-nav{display:flex;gap:14px;margin-left:auto}
.main-nav a{color:#333;text-decoration:none;padding:8px;border-radius:6px}
.main-nav a.cta{background:var(--accent);color:#fff}
.try-btn{margin-left:12px;background:transparent;border:1px solid var(--accent);color:var(--accent);padding:8px 10px;border-radius:8px}
.menu-toggle{display:none}

/* hero */
.hero{padding:64px 0;background-image:url('/assets/img/pattern.svg');background-repeat:repeat;background-size:220px}
.hero-inner{background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(255,255,255,0.95));padding:36px;border-radius:12px;box-shadow:var(--shadow)}
.lead{color:var(--muted);margin-top:6px}
.hero-actions{margin-top:18px;display:flex;gap:12px}
.primary{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none}
.secondary{background:transparent;border:1px solid var(--accent-2);color:var(--accent-2);padding:10px 14px;border-radius:8px}
.meta{margin-top:10px;color:var(--muted);font-size:0.9rem}

/* sections */
section{padding:48px 0}
h2{margin:0 0 18px 0;color:var(--accent-2)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:18px;list-style:none;padding:0}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
.cards article{background:var(--card);padding:18px;border-radius:10px;box-shadow:var(--shadow)}
.case-notes ol{padding-left:18px}
.clinician{color:var(--muted);font-size:0.9rem}

/* footer */
.site-footer{border-top:1px solid rgba(20,20,20,0.04);padding:28px 0;background:transparent}
.site-footer .container{display:flex;gap:18px;align-items:flex-start}
.footer-left p{margin:0}
.footer-right{flex:1;color:var(--muted);font-size:0.9rem}

/* modal */
.modal{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:28px;background:rgba(10,10,10,0.35);visibility:hidden;opacity:0;transition:opacity 200ms ease, visibility 200ms}
.modal[aria-hidden="false"]{visibility:visible;opacity:1}
.modal-dialog{background:var(--card);padding:20px;border-radius:12px;max-width:640px;width:100%;box-shadow:0 20px 40px rgba(10,10,10,0.18);position:relative}
.modal-close{position:absolute;top:12px;right:12px;background:transparent;border:0;color:var(--muted)}
.try-tabs{display:flex;gap:8px;margin-top:8px}
.try-tabs button{background:transparent;border:1px solid rgba(0,0,0,0.06);padding:8px;border-radius:8px}
.try-tabs button.active{background:var(--accent);color:#fff;border-color:var(--accent)}
.try-views .view{margin-top:12px}
textarea,input{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(10,10,10,0.08)}
.controls{display:flex;gap:8px;margin-top:10px}
.controls button{padding:8px 10px;border-radius:8px;border:0;background:var(--accent-2);color:#fff}
.controls button[disabled]{opacity:0.5}
.muted{color:var(--muted)}
.small{font-size:0.85rem}

/* breath visual */
.breath-svg{width:140px;height:140px;display:block;margin:12px auto}
.breath-svg circle{fill:var(--accent);opacity:0.12;transition:transform 600ms ease,opacity 600ms}
.breathing .breath-svg circle{transform:scale(1.8);opacity:0.22}

/* reveal animations */
.reveal{opacity:0;transform:translateY(12px);transition:opacity 420ms ease,transform 420ms ease}
.reveal.visible{opacity:1;transform:none}

/* reduced motion */
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none !important;transform:none !important;opacity:1 !important}
}

/* responsive */
@media (max-width:800px){
  .main-nav{display:none}
  .menu-toggle{display:inline-block}
  .hero-inner{padding:20px}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function qs(sel, ctx){return (ctx||document).querySelector(sel)}
  function qsa(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year in footer
  qs('#year').textContent = new Date().getFullYear();

  // Modal logic
  var modal = qs('#try-modal');
  var openBtns = [qs('#open-try'), qs('#open-try-cta')].filter(Boolean);
  var closeBtn = qs('#close-try');
  var body = document.body;

  function openModal(){
    modal.setAttribute('aria-hidden','false');
    body.style.overflow='hidden';
  }
  function closeModal(){
    modal.setAttribute('aria-hidden','true');
    body.style.overflow='';
    stopBreathing();
  }

  openBtns.forEach(function(b){b.addEventListener('click',openModal)});
  if(closeBtn) closeBtn.addEventListener('click',closeModal);
  modal.addEventListener('click', function(e){ if(e.target===modal) closeModal(); });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeModal(); });

  // Tabs inside modal
  var tabs = qsa('.try-tabs button');
  var views = qsa('.try-views .view');
  tabs.forEach(function(tab){
    tab.addEventListener('click', function(){
      tabs.forEach(function(t){t.classList.remove('active')});
      tab.classList.add('active');
      var mode = tab.getAttribute('data-mode');
      views.forEach(function(v){
        if(v.getAttribute('data-mode')===mode){ v.removeAttribute('hidden'); } else { v.setAttribute('hidden',''); }
      });
    });
  });

  // Breathing exercise
  var startBtn = qs('#start-breath');
  var stopBtn = qs('#stop-breath');
  var breathVisual = qs('#breath-visual');
  var breathInterval = null;
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function breatheCycle(){
    // Expand then hold then contract using classes
    body.classList.add('breathing');
    setTimeout(function(){ body.classList.remove('breathing'); }, 12000); // full cycle length
  }
  function startBreathing(){
    if(reduced){ // if reduced motion, provide silent textual cues
      alert('Breathing practice started. Inhale 4, hold 2, exhale 6. Repeat a few times.');
      return;
    }
    breatheCycle();
    breathInterval = setInterval(breatheCycle, 12000);
    startBtn.disabled = true; stopBtn.disabled = false;
  }
  function stopBreathing(){
    if(breathInterval) { clearInterval(breathInterval); breathInterval=null; }
    body.classList.remove('breathing');
    startBtn.disabled = false; stopBtn.disabled = true;
  }

  if(startBtn) startBtn.addEventListener('click', startBreathing);
  if(stopBtn) stopBtn.addEventListener('click', stopBreathing);

  // Journaling save
  var saveJournal = qs('#save-journal');
  var clearJournal = qs('#clear-journal');
  var journalText = qs('#journal-text');
  function journalKey(){ return 'private_therapist_journal_v1'; }
  if(journalText){
    journalText.value = localStorage.getItem(journalKey()) || '';
  }
  if(saveJournal) saveJournal.addEventListener('click', function(){
    localStorage.setItem(journalKey(), journalText.value || '');
    saveJournal.textContent = 'Saved';
    setTimeout(function(){ saveJournal.textContent = 'Save'; },1500);
  });
  if(clearJournal) clearJournal.addEventListener('click', function(){
    journalText.value=''; localStorage.removeItem(journalKey());
  });

  // Intention save
  var saveIntention = qs('#save-intention');
  var clearIntention = qs('#clear-intention');
  var intentionText = qs('#intention-text');
  function intentionKey(){ return 'private_therapist_intention_v1'; }
  if(intentionText){ intentionText.value = localStorage.getItem(intentionKey()) || ''; }
  if(saveIntention) saveIntention.addEventListener('click', function(){
    localStorage.setItem(intentionKey(), intentionText.value || '');
    saveIntention.textContent = 'Saved';
    setTimeout(function(){ saveIntention.textContent = 'Save intention'; },1200);
  });
  if(clearIntention) clearIntention.addEventListener('click', function(){ intentionText.value=''; localStorage.removeItem(intentionKey()); });

  // Simple menu toggle for small screens
  var menuToggle = qs('.menu-toggle');
  var mainNav = qs('.main-nav');
  if(menuToggle && mainNav){
    menuToggle.addEventListener('click', function(){
      var open = menuToggle.getAttribute('aria-expanded') === 'true';
      menuToggle.setAttribute('aria-expanded', String(!open));
      mainNav.style.display = open ? 'none' : 'flex';
    });
  }

  // Scroll reveal with prefers-reduced-motion support
  var revealEls = qsa('.reveal');
  var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(prefersReduced){
    revealEls.forEach(function(el){ el.classList.add('visible'); });
  } else if('IntersectionObserver' in window){
    var ro = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){ entry.target.classList.add('visible'); ro.unobserve(entry.target); }
      });
    },{root:null,threshold:0.12});
    revealEls.forEach(function(el){ ro.observe(el); });
  } else {
    // fallback: reveal all
    revealEls.forEach(function(el){ el.classList.add('visible'); });
  }

})();"} 
